import type { MessageKey } from "@/lib/messages.en";

/**
 * Russian wording, typed against the English catalogue: a key that English adds
 * and Russian has not translated yet is simply left out here, and the English
 * sentence shows in its place (the catalogue store in i18n.ts falls back to it).
 * `npm run i18n:status -- ru` lists what is still missing after a release.
 *
 * Множественные числа. Русский требует трёх форм («1 деталь», «2 детали»,
 * «5 деталей»), а каталог знает две: `…One` и `…Many`. Чтобы не выходило
 * «Выделено 2 объектов», строки `…Many` сформулированы без согласования по
 * падежу — «Выделено: {count}», «Проектов: {count}». Настоящее склонение
 * потребовало бы Intl.PluralRules и правки всех мест вызова.
 *
 * Кавычки — «ёлочки», поэтому экранировать в значениях нечего.
 */
