  "lid.cornerScrewsHint": "Крышку держат четыре винта. В каждом углу тела появляется отверстие шириной {hole} мм и глубиной {depth} мм, в столбике там, где стенка слишком тонкая, а в крышке — отверстие над ним. Напечатанные отверстия выходят чуть меньше нарисованных: сначала попробуй на пробной детали.",
