  "lid.hingeStyleHint.flush": "В стенке: коробка сохраняет размеры, крышка открывается примерно на 140°.",
  "lid.hingeStyleHint.pivot": "Крышка лежит на уступе в проёме и поворачивается на двух осях через боковые стенки, примерно до 95°.",
