  "status.lidMadeHingeFlush": "Крышка готова ({type}) с шарниром заподлицо: {count} петель в стенке и отверстие для оси {pin} мм. Крышка лежит перевёрнутой рядом с корпусом, готовая к печати.",
  "status.lidMadePivot": "Поворотная крышка готова: она лежит на уступе в проёме и поворачивается на двух осях {pin} мм через боковые стенки. Крышка лежит перевёрнутой рядом с корпусом, готовая к печати.",
  "lid.hingeHint": "Петли чередуются на корпусе и крышке, через все идёт отверстие для оси. 1,75 мм подходит для кусочка филамента, печатная ось держит примерно от 3 мм. Петли {diameter} мм.",
  "lid.latches": "Замки",
  "lid.latchBack": "Замки и сзади",
  "lid.leaveOpenings": "Оставлять сквозные отверстия открытыми",
  "lid.leaveOpeningsHint": "Отверстие, которое проходит через всё тело насквозь, например трубка посередине круглой коробки, остаётся открытым и в крышке. Остальное крышка закрывает.",
  "lid.latchWidth": "Ширина защёлки",
  "lid.latchGrip": "Натяг защёлки",
  "lid.latchInPlace": "Печатать защёлки на крышке",
  "lid.latchInPlaceHint": "Каждая защёлка печатается на своём штифте у края крышки, закрытой, как на коробке, и с зазором, чтобы поворачиваться: крышка и защёлки печатаются за один раз, перевёрнутыми. Перед тем как надеть крышку, откиньте защёлки наружу. Её гнездо на штифте — замкнутое кольцо, поэтому она не может соскочить. Штифт {pin} мм.",
  "lid.preview": "Показывать предпросмотр рядом с коробкой",
  "lid.preview.working": "Предпросмотр рассчитывается …",
  "lid.preview.hint": "Серым: крышка, которую дадут эти настройки, с отдельными деталями и тем, что добавится к коробке. Ничего не создаётся до нажатия «Сделать крышку».",
  "lid.preview.none": "Нет предпросмотра: {reason}",
  "lid.preview.text": "В теле есть текст, он замедлял бы вид при каждом изменении. «Сделать крышку» рассчитает её как обычно.",
  "lid.preview.failed": "Не удалось рассчитать предпросмотр. «Сделать крышку» всё равно попробует.",
  "lid.preview.show": "Показать",
  "lid.latchHint": "Защёлка надевается на штифт под краем и на штифт на кромке крышки, как на коробке для аккумуляторов камеры, и в открытом виде висит на крышке. Защёлки лежат рядом с крышкой и печатаются на боку. Штифт {pin} мм.",
  "lid.latchHintHinge": "На стороне напротив петли. Защёлка надевается на штифт под краем и на штифт на кромке крышки и в открытом виде висит на крышке. Защёлки лежат рядом с крышкой и печатаются на боку. Штифт {pin} мм.",
  "lid.error.latchLidType": "Замки ставятся на крышку «Вставная» или «Плоская», лежащую на краю, но не на крышку на поворотных осях.",
  "lid.error.latchHandle": "Замки стоят там, где была бы ручка: выберите замки или ручку.",
  "lid.error.latchSideShort": "На стороне для замков (спереди или напротив петли) нет достаточно длинного прямого участка для стольких замков такой ширины. Возьмите меньше замков или более узкую защёлку.",
  "lid.error.latchBodyLow": "Корпус слишком низкий для замков: защёлка с язычком уходит на {height} мм ниже края.",
