  "lid.latchClipsName": "{name}: защёлки замков",
  "status.lidLatches": "Замков: {count}, защёлки рядом с крышкой, штифты {pin} мм.",
  "lid.hingeTypeHint": "Шарнир подходит к вставной или плоской крышке.",
  "lid.hingeKnucklesName": "{name} петли шарнира",
  "lid.hingePinName": "{name} ось шарнира",
  "lid.hingeEndPlugs": "Заглушки на концах",
  "lid.hingeEndPlugsHint": "Квадратная заглушка закрывает каждый конец отверстия под ось заподлицо с наружной стороной коробки: ось не видна и не может выскользнуть. Сначала вставьте ось, затем вдавите заглушки. Ось из-за них короче: строка состояния сообщает её длину.",
  "lid.hingeEndPlugsName": "{name} заглушки шарнира",
