  "lid.error.endPlugsShort": "Петли на концах слишком короткие для заглушек: каждой нужно не меньше 3,5 мм. Возьмите меньше петель.",
  "status.lidMadeHingeFlushPlugs": "Крышка готова ({type}) с шарниром заподлицо: {count} петель в стенке, отверстие для оси {pin} мм длиной {length} мм и две заглушки, которые его закрывают. Крышка и заглушки лежат рядом с корпусом, готовые к печати.",
  "status.lidMadeHingeFlushCorners": "Крышка готова ({type}) с шарниром заподлицо: {count} петель в стенке, крайние заполняют скруглённые углы, и отверстие для оси {pin} мм длиной {length} мм. Крышка лежит перевёрнутой рядом с корпусом, готовая к печати.",
  "lid.error.hingeLidType": "Шарнир подходит только к вставной или плоской крышке: бортик снаружи при открывании упёрся бы в заднюю стенку.",
  "lid.error.hingeNoBack": "На выбранной стороне нет места для трёх петель: она слишком короткая или слишком изогнутая.",
  "lid.error.hingeTooLow": "Корпус слишком низкий для шарнира: под петлями нужно место для их скоса. Возьмите ось тоньше или корпус выше.",
  "lid.error.hingeKernel": "Не удалось соединить шарнир с корпусом.",
