  "lid.clickBumpHeight": "Высота выступов",
  "lid.clickBumpHeightHint": "Насколько каждый выступ заходит в стенку корпуса. Меньше — для маленькой коробки или жёсткого бортика, больше — для более чёткого щелчка.",
  "lid.clickDimplesName": "{name} углубления защёлок",
  "lid.error.clickBumpsNoLip": "Защёлкивающимся выступам нужен бортик или обод: возьми вставную, надевающуюся или двустороннюю крышку без поворотных осей.",
  "lid.error.clickBumpsNoRoom": "Для защёлкивающихся выступов нет места: вдали от шарнира и выемки под палец бортику или ободу нужна прямая сторона не короче 12 мм или круглый контур.",
