  "lid.handleHint.tab": "Язычок толщиной с пластину, выступающий на 6 мм за её передний край (или край напротив шарнира), чтобы потянуть за него и открыть крышку.",
  "lid.handleHint.notch": "Углубление в передней стенке корпуса (или в стенке напротив шарнира) прямо под краем крышки, чтобы поддеть её пальцем; 0,8 мм стенки всегда остаётся.",
