  "shell.edges.round": "Скруглённые",
  "shell.edges.sharp": "Острые",
  "shell.edgesHint": "Применяется там, где внутренние стенки расходятся: на уступе или у проёма. Углы обычного прямоугольного тела внутри останутся острыми — сначала скруглите внешние кромки, чтобы скруглёнными были и внутренние.",
  "shell.stack": "Штабелируемая",
  "shell.stackHeight": "Высота ножки",
  "shell.stackHint": "Низ становится ножкой, уже на толщину стенки, которая входит в проём нижней коробки, как штабелируются контейнеры Gridfinity. Выше коробка расширяется под 45°, поэтому печатается без поддержек; дно лежит над ножкой. Верх не меняется, поэтому подходит любая крышка.",
  "shell.stackWallThin": "Стенка слишком тонкая для штабелирования: не меньше {min}.",
