  "shell.errorStackNotStraight": "Стенки не вертикальны: низ не так широк, как верх, и коробка не войдёт в следующую. Выключите штабелирование.",
  "shell.errorStackFailed": "Ножку не удалось построить на этом теле. Выключите штабелирование или выберите другую стенку.",
  "shell.shelf": "Полочный выступ",
