  "shell.errorTooSlow": "Создание оболочки для этого тела заняло слишком много времени и было остановлено; ничего не изменилось. Ядро CAD не может рассчитать стенки для этой формы. Попробуйте более тонкую стенку или другие открытые стороны.",
