  "status.edgeRemoveChanged": "Объект изменился при удалении обработки кромки; попробуйте ещё раз",
  "status.groupChanged": "Сцена изменилась при группировке; выберите объекты и попробуйте ещё раз",
  "status.computing": "Идёт расчёт… можно продолжать работу",
  "status.computeTimedOut": "Расчёт занял слишком много времени и был остановлен. Попробуйте меньше объектов или более простые",
  "status.intersectChanged": "Сцена изменилась при пересечении; выберите объекты и попробуйте ещё раз",
  "status.noPrintableSurface": "У выбранного объекта нет поверхности, пригодной для печати",
  "status.onlyOnePart": "У выбранного объекта только одна связная часть",
  "status.meshTooDense": "В этой сетке {triangles} треугольников. Этот инструмент выдерживает {limit}; сверх этого ядро считает дольше, чем разумно ждать. Для фигуры из списка фигур пока используйте её собственные настройки. Любую другую сетку, например импортированную деталь, уменьшите правым щелчком и командой «Упростить сетку»; импортированную деталь можно также загрузить как STEP.",
  "status.meshDenseAsk": "В этой сетке {triangles} треугольников — больше, чем {limit}, на которые рассчитан этот инструмент. Дальше это может занять много минут, страница может зависнуть, а всё несохранённое пропадёт, если её придётся закрыть. Сначала сохраните проект.\n\nВсё равно попробовать?",
  "status.threadTooDense": "Резьба строится из {triangles} треугольников — слишком много для обработки кромок, которая останавливается на {limit}. Поэтому добавляйте резьбу после обработки кромок: сначала фаска или скругление тела, потом резьба. Фаска головки в свойствах сразу обрабатывает кромку головки винта — без этого обходного пути.",
  "status.vaseTooDense": "В этой вазе {triangles} треугольников — больше, чем {limit}, с которыми справляются выдалбливание и обработка кромок. Ваза сама становится полой и имеет свою крышку: в разделе «Исполнение» выбери «Полая со стенкой», а крышку — на карточке «Принадлежности».",
  "status.unlockImageDelete": "Снимите блокировку с изображения эскиза клавишей L, прежде чем удалять его",
  "status.unlockImageEdit": "Снимите блокировку с изображения эскиза клавишей L, прежде чем изменять его",
  "status.updatingRevolve": "Обновление предпросмотра вращения…",
  "status.waitForPreview": "Дождитесь подходящего предпросмотра кромки, прежде чем применять",
  "status.deletedOne": "Удалена 1 фигура",
  "status.deletedMany": "Удалено фигур: {count}",
  "status.cutTooComplex": "Геометрия слишком сложна для разделения: {triangles} треугольников, лимит — {limit}. Сначала упростите полигональную сетку или увеличьте лимит в настройках рабочей области.",
  "status.groupNotMerged": "Сгруппировано, но не объединено в одно тело: вместе у частей {triangles} треугольников, больше лимита {limit}. При экспорте они остаются наложенными друг на друга, и слайсеры сообщают об этом как об ошибках (non-manifold рёбра). Увеличьте лимит в настройках рабочей области или упростите сетку, затем сгруппируйте снова.",
  "status.cutNotWatertightTooComplex": "Эта полигональная сетка не герметична, и при {triangles} треугольниках она слишком сложна для резервного разделения (лимит {limit}). Сначала восстановите или упростите сетку.",
