  "gear.profileRound": "Круглый",
  "gear.roundHint": "Круглые зубья из дуг: легче печатаются на малых шестернях и дают плавный захват на ручках. Делительная окружность {pitch} мм. Зацепляется с любой шестерней с круглыми зубьями модуля {module}; межосевое расстояние = (число зубьев + число зубьев) × модуль / 2.",
