  "prop.screwHoleSizeCountersinkHint": "Задаёт стержень и диаметр головки для винта с потайной головкой этого размера: отверстие под крепёж по ISO 273, среднее, зенковка по ISO 15065 под 90°. Дюймовые размеры от #2 до #14 по ASME B18.6.1 под 82°; они же австралийские gauge (6-gauge = #6). Длина сохраняется.",
