  "latch.pinsHint": "Два штифта со щёчками, чтобы сгруппировать с коробкой и крышкой. Клипсу сделайте через «Только клипса» с той же шириной и хваткой.",
  "latch.clipHint": "Только клипса, лёжа на боку, как она печатается. Подходит к любой застёжке с той же шириной клипсы и хваткой, и к застёжкам инструмента крышки.",
