  "surfaceTexture.barkBeech": "Бук",
  "surfaceTexture.barkOakHint": "Глубокие борозды между длинными округлыми гребнями, сливающимися в сеть.",
  "surfaceTexture.barkPineHint": "Длинные пластины между бороздами, каждая на своей высоте, в шелушащихся слоях.",
