  "import.referenceImage": "Эталонное изображение",
  "import.referenceImageHint": "Картинка для выравнивания деталей, положенная на стол или на грань, на которой лежит рабочая плоскость. Она никогда не печатается и не экспортируется.",
  "referenceImage.title": "Эталонное изображение",
  "referenceImage.cardHint": "Картинка для выравнивания деталей. Она никогда не печатается, не экспортируется и не группируется. Заблокируйте её в заголовке, чтобы она оставалась на месте; через заблокированную картинку проходят щелчки.",
  "referenceImage.lockedHint": "Заблокировано: щелчки проходят на стол. Разблокируйте её в заголовке, чтобы двигать, делать прозрачнее или калибровать.",
