  "import.divider": "или добавьте геометрию",
  "import.dropZone": "Перетащите файлы STL, OBJ (вместе с .mtl или в виде ZIP), 3MF, STEP, SVG, DXF, PNG или JPG",
  "import.dropZoneHint": "или щёлкните, чтобы выбрать на компьютере",
  "import.keepSvgPage": "SVG: сохранить положение на листе чертежа",
  "import.keepSvgPageHint": "Чертежи, выполненные на одном листе, — например слои одного документа, экспортированные отдельными файлами, — при последовательном импорте снова совмещаются. Без этой опции каждый чертёж центрируется сам по себе.",
  "import.keepMeshPosition": "STL, OBJ, 3MF: сохранить положение из файла",
  "import.keepMeshPositionHint": "Части одной модели, экспортированные отдельными файлами, — например туловище, руки и ноги миниатюры, — при последовательном импорте снова встают на свои места: каждая оказывается там, где её помещает файл, а начало координат файла — в центре стола. Без этой опции каждый файл ставится отдельно у центра стола.",
  "import.color": "Цвет импортированных тел",
  "import.colorHint": "Цвет, с которым появляется тело, если файл его не задаёт, например STL или STEP с одним телом. Файлы со своими цветами их сохраняют.",
  "import.colorReset": "Вернуть обычный цвет",
  "import.svgWidth": "SVG и картинка: ширина, мм",
  "import.svgWidthHint": "Введите ширину, с которой чертёж или картинка войдёт при импорте; пусто — собственный размер. Действует только для следующего импорта.",
  "import.svgWidthPlaceholder": "свой размер",
  "import.svgSizeKeepHint": "Размер остаётся в поле после импорта, так что каждый следующий чертёж загружается с ним, в том числе при следующем открытии layerling. Без галочки он действует только для следующего импорта.",
  "import.svgSizeKeep": "Оставить для следующих импортов",
  "import.svgSizeAsHeightHint": "Чертёж или изображение загружается такой высоты, а не такой ширины, измеренной на его странице; на столе это его глубина.",
