  "workspace.showViewBar": "Показывать панель вида",
  "workspace.showViewBarHint": "Если выключено, панели вида в 3D-редакторе нет; клавиши, мышь и куб вида работают. Инструменты измерения исчезают вместе с ней, если у них нет своей панели.",
  "workspace.measureBar": "Инструменты измерения на своей панели",
  "workspace.measureBarHint": "Рулетка, угольник и транспортир стоят на панели, которую можно двигать и сворачивать, а не на панели вида.",
  "workspace.showStepNotices": "Показывать сообщение после каждого шага",
  "workspace.showStepNoticesHint": "Короткое сообщение рядом с кубом вида после шага, например объединения, с кнопкой «Отменить». Выключите, если мешает; сообщения, которые чего-то ждут от вас или сообщают о проблеме, по-прежнему появляются, а «Отменить» на ленте по-прежнему называет шаг при наведении.",
  "workspace.viewCubeKeepsTurn": "Сверху и Снизу сохраняют поворот вида",
  "workspace.viewCubeKeepsTurnHint": "Щелчок по граням Сверху или Снизу на кубе вида, или клавиши 5 и 6, смотрит прямо вниз или вверх, но оставляет вид повёрнутым, как он стоит, с округлением до ближайшей четверти оборота. Если выключено, перед всегда внизу.",
  "workspace.startView": "Начальный вид",
  "workspace.startViewHint": "Ракурс, в котором открываются новые проекты и к которому возвращает «Домой». Поверните вид как вам нравится и возьмите текущий вид. Действует для всех проектов в этом браузере.",
