  "workspace.doubleClickCentersView": "Двойной щелчок по рабочей плоскости центрирует там вид",
  "workspace.selectBeforeMoving": "Выделять перед перемещением",
  "workspace.pasteCentered": "Вставлять в центр и опускать",
  "workspace.pasteCenteredHint": "При вставке детали вместе помещаются в центр рабочей плоскости и опускаются на неё, а не остаются там, откуда пришли. Полезно для деталей, скопированных из других программ: они могут оказаться далеко от платформы.",
  "workspace.moveAlongShapeAxes": "Двигать вдоль собственных осей фигуры",
  "workspace.moveAlongShapeAxesHint": "Если выделена повёрнутая или наклонённая фигура, клавиши-стрелки, перетаскивание и красный, зелёный и вертикальный (вверх/вниз) маркеры двигают её вдоль её собственных осей, а не по сетке, а розовые направляющие выравнивают её по фигурам, повёрнутым так же. Удерживайте J, чтобы вместо этого двигать по сетке.",
  "workspace.showShapeWorkplaneWhileMoving": "Показывать рабочую плоскость фигуры при перемещении",
  "workspace.showShapeWorkplaneWhileMovingHint": "Пока повёрнутая или наклонённая фигура движется вдоль собственных осей (J зажата или включено «Двигать вдоль собственных осей фигуры»), показывается рабочая плоскость, выровненная по фигуре. Это только подсказка: рабочая плоскость и место, куда встают новые фигуры, остаются прежними.",
  "workspace.frameByDirection": "Направление рамки решает",
  "workspace.frameByDirectionHint": "Рамка, проведённая вправо, выделяет только то, что целиком внутри неё, влево — всё, чего она касается (рисуется пунктиром), как в SketchUp",
  "workspace.objectSnap": "Привязка к другим фигурам при перемещении и изменении размера",
  "workspace.stlAsDownload": "Сохранять STL как загрузку",
  "workspace.stlAsDownloadHint": "Chrome и Edge каждый раз записывают STL в один и тот же файл. Включите это, чтобы получать обычную загрузку: тогда браузер нумерует файлы, имя (1).stl, имя (2).stl.",
  "workspace.lylAsDownload": "Сохранять проекты как загрузку",
  "workspace.lylAsDownloadHint": "На некоторых ПК окно сохранения Chrome и Edge не возвращает файл. Включите это, чтобы обойтись без него: Экспорт > LYL, Ctrl+S и «Сохранить как» тогда всегда кладут проект в папку «Загрузки».",
  "workspace.confirmTabClose": "Спрашивать перед закрытием вкладки",
  "workspace.confirmTabCloseHint": "Если открыт проект, браузер при закрытии или перезагрузке вкладки задаёт свой стандартный вопрос «Покинуть сайт?». Проекты и так сохраняются после каждого изменения, вопрос — лишь напоминание. Формулировку задаёт браузер.",
  "workspace.softLighting": "Мягкий свет",
  "workspace.softLightingHint": "Основной свет идёт оттуда, откуда вы смотрите, и поворачивается вместе с видом, поэтому ни одна грань не остаётся тёмной и не засвечивается до белого. Тени остаются.",
