  "mold.subtitle": "Литейная форма или пуансон и матрица из выбранной мастер-модели",
  "mold.help": "Выбранное тело — мастер-модель: форма, которую вы хотите отлить или отпрессовать. Новые детали располагаются рядом с ней так, как они печатаются; мастер-модель остаётся без изменений.",
