  "mold.kind": "Создать",
  "mold.kind.twoPart": "Разъёмная форма",
  "mold.kind.box": "Опалубка для силикона",
  "mold.kind.tray": "Открытая форма",
  "mold.kind.die": "Пуансон и матрица",
  "mold.kindHint.twoPart": "Жёсткая форма из двух половин, которую печатают и сразу заливают: смола, гипс, воск, мыло, шоколад или бетон. Центрирующие конусы совмещают половины, воронка и воздухоотводы впускают материал и выпускают воздух.",
  "mold.kindHint.box": "Рамка и опорная плита, чтобы залить силиконом напечатанную мастер-модель. Силиконовая форма передаёт каждую деталь и отпускает даже поднутрения, которые застряли бы в жёсткой форме.",
  "mold.kindHint.tray": "Цельная форма, открытая сверху, для деталей с плоской стороной: плоская сторона становится открытым верхом, заливается вровень с краем. Просто, без литника.",
  "mold.kindHint.die": "Пуансон и подходящая к нему матрица, чтобы формовать, тиснить или вырубать тонкий материал: кожу, картон, фольгу или тонкий металл. Пуансон — это контур мастер-модели, видимый сверху.",
