  "lid.boltHint": "Шпингалет, напечатанный сразу в трубке на стенке корпуса. Поднимите его за ручку в гнездо выступа крышки и поверните ручку на уступ: он останется наверху и удержит крышку. Поверните обратно — он опустится, крышка свободна.",
