  "lid.latchStyle.snap": "Защёлки-крючки",
  "lid.snapUndercut": "Поднутрение",
  "lid.snapHint": "Защёлки-крючки из библиотеки фигур, печатаются вместе с крышкой: каждый свисает с края крышки и защёлкивается под упором на стенке ниже кромки. Плечо длиной {arm} мм, поэтому в PLA оно гнётся, не ломаясь. Чтобы открыть, потяните язычок у основания крючка наружу.",
  "lid.latchCatchesName": "{name} упоры",
  "status.lidSnapHooks": "Защёлок-крючков на крышке: {count}, напечатаны вместе с ней и защёлкиваются под упорами на корпусе. Чтобы открыть, потяните язычок у основания крючка наружу. Плечо {arm} мм.",
  "lid.stackTop": "Лоток для штабелирования сверху",
  "lid.stackTopHint": "Крышка печатается стоя и несёт сверху в лотке следующую штабелируемую коробку (Выдолбить, Штабелируемая). С петлёй за задней стенкой она такой высоты, какая нужна шарнирам, чтобы печататься без поддержек.",
  "lid.error.hingeAlready": "У этого тела уже есть петля от прежней крышки; её шарниры выступают над краем. Сначала отмените ту крышку (Ctrl+Z) или разгруппируйте тело и удалите шарниры петли.",
  "lid.error.stackTopType": "Лоток для штабелирования пока не работает с этим видом крышки или петли.",
  "lid.error.stackTopExtras": "Лоток для штабелирования пока не работает с магнитами, щелчковыми выступами, ручкой, держателем крышки или откидной крышкой.",
  "shell.stackLidHint": "Плоская крышка с такой же ножкой, как у коробки, рядом с ней: входит в коробку, а следующая коробка встаёт в её бортик.",
  "shell.stackHollow": "Полая ножка",
  "shell.stackHollowHint": "Ножка — это только стенка, дно лежит на столе: меньше пластика и больше места внутри. Скос сохраняет толщину стенки.",
  "shell.stackHollowGrid": "Дно Gridfinity стоит на сплошной ножке, поэтому ножка остаётся сплошной.",
