  "shell.stackGripHint": "Выемка для пальца внизу посередине каждой выбранной стороны, чтобы снять коробку с нижней. Её потолок под 45 градусов, поэтому она печатается без поддержек.",
  "shell.stackLid": "Подходящая крышка для штабеля",
  "shell.errorChangedAfter": "Тело изменили после выдалбливания (например, магнитами из инструмента «Крышка»), поэтому его нельзя выдолбить снова. Сначала отмените этот шаг в истории, затем измените выдалбливание.",
  "shell.grid": "Дно Gridfinity",
  "shell.gridCells": "Ячейки в дне",
  "shell.gridFit": "Подогнать стенки под сетку",
  "shell.gridHint": "Базовая плита Gridfinity в дне: гнездо для каждой ячейки, столько, сколько задано (не больше, чем помещается). Дно становится толщиной 6,2 мм. С подгонкой стенки утолщаются, так что внутренность — ровно ячейки с зазором 0,5 мм.",
