  "shell.gridMagnets": "Отверстия под магниты",
  "shell.gridMagnetsHint": "Четыре отверстия 6,5 × 2,4 мм под каждым гнездом, там, где стоят магниты контейнера (13 мм от середины ячейки), для магнитов 6 × 2 мм. Дно становится толщиной 8,6 мм, чтобы под отверстиями оставалось 1,2 мм.",
  "shell.gridScrews": "Отверстия под винты",
