  "mold.warning.noSprue": "Литник не задан, поэтому форму нельзя залить: поставьте его на мастер-модель.",
  "mold.kind.skin": "Тонкая силиконовая форма с кожухом",
  "mold.kind.core": "Форма с сердечником для сосуда",
  "mold.kind.halves": "Две ванночки для половин формы",
  "mold.kindHint.skin": "Тонкая силиконовая форма с напечатанным кожухом, который не даёт ей деформироваться. Мастер-модель стоит на опорной плите, кожух над ней оставляет зазор со всех сторон, и силикон заливается в этот зазор через верх кожуха. Силикона уходит лишь малая часть того, что нужно для опалубки.",
  "mold.kindHint.core": "Для сосуда, открытого сверху, например кашпо, стакана или вазы: опорная плита с сердечником, который заполняет внутреннюю часть, и оболочка вокруг наружной стороны. Отливают вверх дном, краем сосуда на плите, и заливают вровень с краем формы: бетон, гипс или смола.",
  "mold.kindHint.halves": "Две открытые ванночки, в каждой на плите стоит одна половина мастер-модели. Залейте в каждую силикон или гипс — и получите две половины формы с подходящими друг к другу центрирующими выступами и литниковым каналом, не утапливая мастер-модель в пластилин. Гипсовые половины нужны для шликерного литья.",
  "mold.made.skin": "Тонкая силиконовая форма создана рядом с мастер-моделью: опорная плита и кожух, кожух верхом вниз, как он печатается.",
  "mold.made.core": "Форма с сердечником создана рядом с мастер-моделью: основание с сердечником и оболочка.",
  "mold.made.halves": "Две ванночки созданы рядом с мастер-моделью, по одной на каждую половину формы.",
