  "mold.part.caseFirst": "{name} ванночка для первой половины формы",
  "mold.part.caseSecond": "{name} ванночка для второй половины формы",
  "mold.error.noHollow": "Не найдено полости, открытой сверху, поэтому сердечник делать не из чего. Поставьте сосуд отверстием вверх; для сплошной мастер-модели возьмите разъёмную форму.",
  "mold.warning.hotCast": "Этот материал заливают горячим, или он нагревается при застывании: печатайте форму из PETG или ASA, PLA размягчается уже примерно с 55 °C.",
  "mold.warning.coreUndercut": "В глубине сосуд шире, чем у отверстия: жёсткий сердечник не выйдет из отливки. Возьмите сосуд, расширяющийся к отверстию, или отлейте сам сердечник из силикона.",
  "mold.warning.rimCut": "Край неровный: он срезан на {mm} мм ниже, чтобы плита его закрывала.",
  "mold.warning.footFilled": "Углубление под основанием отливается сплошным: форма там заливается вровень с краем.",
  "mold.warning.smallOpening": "Отверстие для заливки маленькое, потому что дно сосуда не плоское: сделайте ему плоское основание.",
  "mold.warning.clayNeedsPlaster": "Шликер застывает только в гипсовой форме, которая вытягивает из него воду: сделайте гипсовые половины с помощью «Две ванночки для половин формы».",
  "mold.warning.seamFallback": "Для заливки через шов нужны половины, которые открываются влево/вправо или вперёд/назад: эта форма заливается сверху.",
  "mold.pieces": "Части",
  "mold.pieces.two": "Две половины",
  "mold.pieces.four": "Четыре части",
  "mold.piecesHint.four": "Четыре части сходятся по двум вертикальным плоскостям, и каждая снимается вбок: для поднутрений со всех сторон, которые застревают в любых двух половинах. Стяните их резинками; литник и воздухоотводы лежат в швах.",
  "mold.pour": "Заливка",
  "mold.pour.top": "Лёжа, сверху",
  "mold.pour.seam": "Стоя, через шов",
  "mold.pourHint.top": "Форма лежит, плоскость разъёма горизонтальна, и литник идёт вниз через верхнюю половину.",
  "mold.pourHint.seam": "Форма стоит верхом мастер-модели вверх; литник лежит в шве, пополам в каждой половине. Обычный способ для фигурок и свечей. Нужны половины, которые открываются влево/вправо или вперёд/назад.",
  "mold.wick": "Отверстие под фитиль свечи",
  "mold.wickDiameter": "Отверстие под фитиль",
  "mold.wickHint": "Отверстие под фитиль напротив литника и прорезь поперёк воронки для палочки, на которой висит фитиль. Поставьте свечу вверх дном, чтобы она заливалась со стороны основания.",
  "mold.seal": "Уплотнительный бортик вокруг полости",
  "mold.boxShape": "Рамка",
  "mold.boxShape.rect": "Прямоугольник",
  "mold.boxShape.contour": "По контуру",
  "mold.boxShapeHint.contour": "Рамка повторяет контур мастер-модели, видимый сверху: меньше силикона, чуть больше печати.",
  "mold.shellSplit": "Из двух половин",
  "mold.shellSplitHint.skin": "Две половины, стянутые болтами по фланцу, снимаются с застывшего силикона легче, чем цельный кожух.",
  "mold.shellSplitHint.core": "Две половины снимаются и с отливки без уклона. Цельная оболочка не может протечь по шву, но ей нужен сосуд, расширяющийся к отверстию.",
