  "mold.moldMaterial.plaster": "Гипс",
  "mold.moldMaterialHint.silicone": "Силиконовые половины отпускают небольшие поднутрения. Около 10 мм вокруг мастер-модели — хорошее начало.",
  "mold.moldMaterialHint.plaster": "Гипсовые половины для шликерного литья: около 25 мм вокруг мастер-модели равномерно вытягивают воду. Выберите «Шликер (глина)» как материал отливки, чтобы форма стала больше на величину усадки изделия.",
