  "mold.castMaterial.wax": "Воск",
  "mold.castMaterial.soap": "Мыло",
  "mold.castMaterial.concrete": "Бетон",
  "mold.castMaterial.clay": "Шликер (глина)",
  "mold.skinHint": "Загерметизируйте мастер-модель, поставьте кожух в паз и прижмите его резинками через вырезы в плите или грузом: силикон его приподнимает. Лейте медленно через воронку, пока силикон не покажется в воздухоотводах. Чтобы лить в готовую форму, поставьте кожух с силиконом внутри на его верх.",
  "mold.coreHint": "Поставьте оболочку на плиту поверх сердечника, стяните всё резинками или струбцинами и перед заливкой жидкого материала заклейте швы скотчем или замажьте пластилином. Используйте разделительный состав.",
  "mold.halvesHint": "Загерметизируйте напечатанные ванночки и используйте разделительный состав. Залейте обе вровень с краем: две половины, которые получатся, подходят друг к другу, а центрирующие выступы в углах их совмещают.",
  "mold.mix": "Что замешать",
