  "boltSplit.error.kernel": "Разрезать не удалось: {message}",
  "inspector.boltSplit": "Разрезать вдоль и положить",
  "inspector.boltSplitHint": "Для печати: разрезано по оси на две половины, каждая лежит на плоскости разреза. Резьба, напечатанная лёжа, намного прочнее, чем стоя. Потом склейте половины.",
  "status.boltSplit": "{name} разрезано вдоль: две половины на плоскостях разреза.",
  "boltSplit.pinsName": "{name} – центрирующие штифты",
  "inspector.boltSplitPins": "С центрирующими штифтами",
  "inspector.boltSplitPinsHint": "Штифты Ø {diameter} мм, один в головке и один–три в резьбе по длине, в отверстиях перпендикулярно плоскости разреза: они точно совмещают половины, в том числе вдоль оси, чтобы витки совпали. Отверстия заканчиваются конусом 45°, всё печатается без поддержек.",
  "inspector.boltSplitFilament": "Филамент вместо штифтов (1,75 мм)",
  "inspector.boltSplitFilamentHint": "Вместо печатных штифтов: отрежьте кусочки филамента 1,75 мм. Один лежит в канале вдоль резьбы, наполовину в каждой половинке, и выравнивает половинки поперёк. Если в головке есть место, второй идёт поперёк головки и выравнивает их ещё и вдоль оси; иначе сдвиньте концы половинок вровень, пока клей не схватится. Работает от M4; печатные штифты помещаются в резьбу только от M6.",
  "status.boltSplitFilament": "{name} разрезан вдоль: две половинки лежат на плоскостях разреза. Отрежьте филамент 1,75 мм: {pieces}.",
  "status.boltSplitFilamentFlush": "{name} разрезан вдоль: две половинки лежат на плоскостях разреза. Отрежьте филамент 1,75 мм: {pieces}. Он выравнивает половинки поперёк; сдвиньте их концы вровень, пока клей не схватится.",
  "status.boltSplitPins": "{name} разрезано вдоль: две половины на плоскостях разреза и центрирующих штифтов: {count}, Ø {diameter} × {length} мм.",
