  "prop.pattiesChamfer": "Фаска для печати",
  "patties.chamferHint": "Для печати пластины стоя на переднем ребре: два угла каждого отверстия, которые тогда оказываются сверху, срезаются под 45° на эту величину; при половине ширины отверстия они сходятся в крышу, которой не нужны поддержки. 0 — без фаски.",
  "patties.chamferRaisedHint": "Для печати пластины стоя на переднем ребре: два угла каждой фигуры, которые тогда оказываются снизу, срезаются под 45° на эту величину; при половине ширины фигуры они сходятся в остриё, которому не нужны поддержки. 0 — без фаски.",
